{
  "name": "opencode-smart-ui",
  "version": "0.2.4",
  "description": "Rich chat UI for opencode: the model renders SVG charts, colored text blocks, structured panels, interactive menus and questionnaires directly in the conversation. Built for the opencode desktop app.",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "smart-ui",
    "charts",
    "desktop"
  ],
  "exports": {
    ".": {
      "import": "./src/index.ts",
      "types": "./src/index.ts"
    }
  },
  "files": [
    "src",
    "README.md"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test \"test/**/*.test.ts\""
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.14.46",
    "@opencode/plugin": "^2.2.5"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "typescript": "^5.6.0"
  }
}
